package br.edu.insper.transacoes;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import org.springframework.web.client.RestClientResponseException; import java.util.List;
@Service public class TransactionService { private final TransactionRepository repository; private final RestClient users; public TransactionService(TransactionRepository repository,@Value("${users.api.base-url}") String url){this.repository=repository;users=RestClient.builder().baseUrl(url).build();} public List<TransactionResponse> list(Long id){return (id==null?repository.findAll():repository.findByClientId(id)).stream().map(TransactionResponse::from).toList();} public TransactionResponse create(CreateTransactionRequest r){try{User u=users.get().uri("/users/{id}",r.clientId()).retrieve().body(User.class);if(u==null||u.email()==null)throw new ClientMissing();return TransactionResponse.from(repository.save(new Transaction(r.clientId(),u.email(),r.stockCode().trim().toUpperCase(),r.quantity(),r.unitPrice(),r.transactedAt())));}catch(RestClientResponseException e){throw new ClientMissing();}} public void delete(Long id){repository.delete(repository.findById(id).orElseThrow(TransactionMissing::new));} record User(Long id,String email){} static class ClientMissing extends RuntimeException{} static class TransactionMissing extends RuntimeException{} }
